import java.util.*;

public class Main {
    public static void main(String[] args) {
        TimeSeriesDB db = new TimeSeriesDB(100); // bucket size of 100 time units, standing in for something like an hour

        db.write(5, 10.0);   // bucket 0
        db.write(50, 20.0);  // bucket 0
        db.write(90, 30.0);  // bucket 0
        db.write(150, 40.0); // bucket 1
        db.write(180, 50.0); // bucket 1

        System.out.println("Query [0,200) before downsampling: " + db.query(0, 200));

        // Bucket 0 ages past retention and is downsampled: its 3 points average to 20.0.
        db.downsampleAndExpire(0);

        System.out.println("Query [0,200) after downsampling bucket 0: " + db.query(0, 200));
    }
}

// Represents either a raw data point or a downsampled rollup value in a
// query result, so the caller can see which resolution each bucket returned.
class QueryResult {
    long bucketStart;
    String kind; // "RAW" or "ROLLUP"
    List<Double> values;

    QueryResult(long bucketStart, String kind, List<Double> values) {
        this.bucketStart = bucketStart;
        this.kind = kind;
        this.values = values;
    }

    public String toString() {
        return "[" + kind + " bucket=" + bucketStart + " values=" + values + "]";
    }
}

// A time series database using time-based chunking: raw points are bucketed
// by timestamp, and a bucket can later be downsampled into a single rollup
// value, freeing its raw points while keeping that time range still queryable.
class TimeSeriesDB {
    private final long bucketSize;
    private final Map<Long, List<Double>> rawPointsByBucket = new TreeMap<>(); // bucketStart -> raw values
    private final Map<Long, Double> rollupsByBucket = new TreeMap<>();            // bucketStart -> aggregated value

    TimeSeriesDB(long bucketSize) {
        this.bucketSize = bucketSize;
    }

    private long bucketFor(long timestamp) {
        return (timestamp / bucketSize) * bucketSize; // floor to this timestamp's bucket start
    }

    void write(long timestamp, double value) {
        long bucket = bucketFor(timestamp);
        rawPointsByBucket.computeIfAbsent(bucket, b -> new ArrayList<>()).add(value);
    }

    // Aggregates a bucket's raw points into one rollup value (a simple average
    // for this worked example), then drops the original raw points.
    void downsampleAndExpire(long bucketStart) {
        List<Double> points = rawPointsByBucket.get(bucketStart);
        double sum = 0;
        for (double v : points) sum += v;
        double average = sum / points.size();
        rollupsByBucket.put(bucketStart, average);
        rawPointsByBucket.remove(bucketStart); // only now, drop the raw data, freeing its space
    }

    // Queries a time range, returning raw points for buckets that still have
    // them, and a rollup for buckets that have already been downsampled.
    List<QueryResult> query(long startInclusive, long endExclusive) {
        List<QueryResult> results = new ArrayList<>();
        for (long bucket = bucketFor(startInclusive); bucket < endExclusive; bucket += bucketSize) {
            if (rawPointsByBucket.containsKey(bucket)) {
                results.add(new QueryResult(bucket, "RAW", rawPointsByBucket.get(bucket)));
            } else if (rollupsByBucket.containsKey(bucket)) {
                results.add(new QueryResult(bucket, "ROLLUP", Collections.singletonList(rollupsByBucket.get(bucket))));
            }
        }
        return results;
    }
}

