#include <iostream>
#include <map>
#include <vector>
#include <string>
using namespace std;

// Represents either a raw data point or a downsampled rollup value in a
// query result, so the caller can see which resolution each bucket returned.
struct QueryResult {
    long bucketStart;
    string kind; // "RAW" or "ROLLUP"
    vector<double> values;
};

void printResult(const QueryResult& r) {
    cout << "[" << r.kind << " bucket=" << r.bucketStart << " values=[";
    for (size_t i = 0; i < r.values.size(); i++) {
        cout << r.values[i];
        if (i + 1 < r.values.size()) cout << ", ";
    }
    cout << "]] ";
}

// A time series database using time-based chunking: raw points are bucketed
// by timestamp, and a bucket can later be downsampled into a single rollup
// value, freeing its raw points while keeping that time range still queryable.
class TimeSeriesDB {
public:
    TimeSeriesDB(long bucketSize) : bucketSize(bucketSize) {}

    long bucketFor(long timestamp) {
        return (timestamp / bucketSize) * bucketSize; // floor to this timestamp's bucket start
    }

    void write(long timestamp, double value) {
        long bucket = bucketFor(timestamp);
        rawPointsByBucket[bucket].push_back(value);
    }

    void downsampleAndExpire(long bucketStart) {
        vector<double>& points = rawPointsByBucket[bucketStart];
        double sum = 0;
        for (double v : points) sum += v;
        double average = sum / points.size(); // a simple average for this worked example
        rollupsByBucket[bucketStart] = average;
        rawPointsByBucket.erase(bucketStart); // only now, drop the raw data, freeing its space
    }

    vector<QueryResult> query(long startInclusive, long endExclusive) {
        vector<QueryResult> results;
        for (long bucket = bucketFor(startInclusive); bucket < endExclusive; bucket += bucketSize) {
            if (rawPointsByBucket.count(bucket)) {
                results.push_back({bucket, "RAW", rawPointsByBucket[bucket]});
            } else if (rollupsByBucket.count(bucket)) {
                results.push_back({bucket, "ROLLUP", {rollupsByBucket[bucket]}});
            }
        }
        return results;
    }

private:
    long bucketSize;
    map<long, vector<double>> rawPointsByBucket; // bucketStart -> raw values
    map<long, double> rollupsByBucket;              // bucketStart -> aggregated value
};

int main() {
    TimeSeriesDB db(100); // bucket size of 100 time units, standing in for something like an hour

    db.write(5, 10.0);    // bucket 0
    db.write(50, 20.0);   // bucket 0
    db.write(90, 30.0);   // bucket 0
    db.write(150, 40.0);  // bucket 1
    db.write(180, 50.0);  // bucket 1

    cout << "Query [0,200) before downsampling: ";
    for (const auto& r : db.query(0, 200)) printResult(r);
    cout << endl;

    // Bucket 0 ages past retention and is downsampled: its 3 points average to 20.0.
    db.downsampleAndExpire(0);

    cout << "Query [0,200) after downsampling bucket 0: ";
    for (const auto& r : db.query(0, 200)) printResult(r);
    cout << endl;

    return 0;
}

